//! ML-DSA-65 (FIPS 204) public keys and signature verification, checked
//! against fixtures generated by CometBFT v0.40.0 (see `support/mldsa65`).
#![cfg(all(feature = "mldsa65", feature = "rust-crypto"))]

use serde_json::Value;
use subtle_encoding::hex;
use tendermint::{
    account,
    block::signed_header::SignedHeader,
    crypto::{default::signature::Verifier, signature::Verifier as _},
    public_key::MlDsa65,
    validator, PublicKey, Signature,
};
use tendermint_proto::{v0_38::crypto::PublicKey as RawPublicKey, Protobuf};

const FIXTURE: &str = include_str!("support/mldsa65/fixture.json");

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).unwrap()
}

fn key_field(name: &str) -> Value {
    fixture()["key"][name].clone()
}

fn key_hex(name: &str) -> Vec<u8> {
    hex::decode(key_field(name).as_str().unwrap()).unwrap()
}

fn public_key() -> PublicKey {
    serde_json::from_value(key_field("pub_key_json")).unwrap()
}

#[test]
fn json_roundtrip_matches_go() {
    let pk = public_key();
    assert_eq!(pk.mldsa65().unwrap().as_bytes(), key_hex("pub_key_hex"));
    assert_eq!(pk.to_bytes(), key_hex("pub_key_hex"));
    assert_eq!(serde_json::to_value(pk).unwrap(), key_field("pub_key_json"));
}

#[test]
fn proto_encoding_matches_go() {
    let pk = public_key();
    let encoded = Protobuf::<RawPublicKey>::encode_vec(pk);
    assert_eq!(encoded, key_hex("pub_key_proto_hex"));
    let decoded = <PublicKey as Protobuf<RawPublicKey>>::decode_vec(&encoded).unwrap();
    assert_eq!(decoded, pk);
}

#[test]
fn address_matches_go() {
    let id = account::Id::from(public_key());
    assert_eq!(id.as_bytes(), key_hex("address_hex"));
}

#[test]
fn from_raw_rejects_wrong_length() {
    let bytes = key_hex("pub_key_hex");
    assert!(PublicKey::from_raw_mldsa65(&bytes).is_some());
    assert!(PublicKey::from_raw_mldsa65(&bytes[1..]).is_none());
    assert!(MlDsa65::try_from(&[0u8; 32][..]).is_err());

    let raw = RawPublicKey {
        sum: Some(tendermint_proto::v0_38::crypto::public_key::Sum::Mldsa65(
            bytes[1..].to_vec(),
        )),
    };
    assert!(PublicKey::try_from(raw).is_err());
}

#[test]
fn verifies_go_signature() {
    let sig = Signature::try_from(key_hex("sig_hex")).unwrap();
    Verifier
        .verify(public_key(), &key_hex("msg_hex"), &sig)
        .unwrap();
}

#[test]
fn rejects_tampered_signature_and_message() {
    let pk = public_key();
    let msg = key_hex("msg_hex");
    let sig = key_hex("sig_hex");

    let mut bad_sig = sig.clone();
    bad_sig[100] ^= 0x01;
    let bad_sig = Signature::try_from(bad_sig).unwrap();
    assert!(Verifier.verify(pk, &msg, &bad_sig).is_err());

    let mut bad_msg = msg.clone();
    bad_msg[0] ^= 0x01;
    let sig = Signature::try_from(sig).unwrap();
    assert!(Verifier.verify(pk, &bad_msg, &sig).is_err());
}

#[test]
fn rejects_signature_with_nonempty_context() {
    let sig = Signature::try_from(key_hex("ctx_sig_hex")).unwrap();
    assert!(Verifier
        .verify(public_key(), &key_hex("msg_hex"), &sig)
        .is_err());
}

#[test]
fn rejects_wrong_length_signature() {
    let sig = key_hex("sig_hex");
    assert!(Signature::try_from(&sig[..sig.len() - 1]).is_err());
    // An Ed25519-sized signature parses but cannot verify under an ML-DSA key.
    let short = Signature::try_from(&sig[..64]).unwrap();
    assert!(Verifier
        .verify(public_key(), &key_hex("msg_hex"), &short)
        .is_err());
}

#[test]
fn validator_set_hash_matches_go() {
    let fixture = fixture();
    let set: validator::Set =
        serde_json::from_value(fixture["light_block"]["validator_set"].clone()).unwrap();
    let expected = key_hex("validator_set_hash");
    assert_eq!(set.hash().as_bytes(), expected);

    let header: SignedHeader =
        serde_json::from_value(fixture["light_block"]["signed_header"].clone()).unwrap();
    assert_eq!(header.header().validators_hash.as_bytes(), expected);
    assert!(set
        .validators()
        .iter()
        .any(|v| matches!(v.pub_key, PublicKey::MlDsa65(_))));
}

#[test]
fn validator_info_from_rpc_json() {
    // The /validators RPC path deserializes `Info` through
    // `deserialize_public_key`, not through the protobuf `ValidatorSet`.
    let fixture = fixture();
    let validators = fixture["light_block"]["validator_set"]["validators"]
        .as_array()
        .unwrap();
    let mut saw_mldsa = false;
    for v in validators {
        let info: validator::Info = serde_json::from_value(v.clone()).unwrap();
        assert_eq!(account::Id::from(info.pub_key), info.address);
        saw_mldsa |= matches!(info.pub_key, PublicKey::MlDsa65(_));
    }
    assert!(saw_mldsa);
}

#[test]
fn protobuf_sum_json_form_matches_go() {
    // CometBFT's JSON for the protobuf key type: {"Sum": {"type": ..., "value": {...}}}
    let go = key_field("pub_key_proto_json");
    let pk = tendermint::public_key::deserialize_public_key(go["value"].clone()).unwrap();
    assert_eq!(pk, public_key());
}
